const STATIC_OUTPUT = new Map();
const DYNAMIC_OUTPUT = [];
const PLACEHOLDER = /\$\{([A-Za-z_][A-Za-z0-9_]*)\}/g;
function compileTemplate(source, translated) {
	const slots = new Map(); let pattern = ""; let last = 0; let index = 1;
	for (const match of source.matchAll(PLACEHOLDER)) {
		pattern += source.slice(last, match.index).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
		pattern += "([\\s\\S]+?)";
		if (!slots.has(match[1])) slots.set(match[1], index);
		index++; last = match.index + match[0].length;
	}
	pattern += source.slice(last).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	return { weight: source.replace(PLACEHOLDER, "").length, re: new RegExp(`^${pattern}$`), render: (matched) => translated.replace(PLACEHOLDER, (token, name) => { const slot = slots.get(name); return slot ? matched[slot] : token; }) };
}
for (const entry of DIALOGUE_DATA) {
	if (entry.d) DYNAMIC_OUTPUT.push(compileTemplate(entry.s, entry.v));
	else STATIC_OUTPUT.set(entry.s, entry.v);
}
DYNAMIC_OUTPUT.sort((a, b) => b.weight - a.weight);
function translateBareOutput(text) {
	const exact = STATIC_OUTPUT.get(text);
	if (exact !== undefined) return exact;
	for (const template of DYNAMIC_OUTPUT) { const match = text.match(template.re); if (match) return template.render(match); }
	return text;
}
/** Translate Verity output; arbitrary unknown text remains untouched. */
export function translateOutput(text) {
	if (typeof text !== "string" || text.length === 0) return text;
	const direct = translateBareOutput(text);
	if (direct !== text) return direct;
	const decorated = text.match(/^(<\u00a7eVerity\u00a7r>\s*)([\s\S]+)$/);
	if (decorated) { const body = translateBareOutput(decorated[2]); return body === decorated[2] ? text : decorated[1] + body; }
	return text;
}

